<script setup lang="ts">
import { computed, ref } from 'vue';
const props = defineProps<{ modelValue: string; name: string; timed: boolean }>();
const emit = defineEmits<{ 'update:modelValue': [value: string] }>();
const open = ref(false); const month = ref(new Date(new Date().getFullYear(), new Date().getMonth(), 1));
function openCalendar() { if (props.modelValue) { const date = new Date(`${props.modelValue.slice(0,10)}T12:00`); if (Number.isFinite(date.getTime())) month.value = new Date(date.getFullYear(),date.getMonth(),1); } open.value = true; }
defineExpose({ openCalendar });
function move(delta: number) { month.value = new Date(month.value.getFullYear(),month.value.getMonth()+delta,1); }
const title = computed(() => month.value.toLocaleDateString(undefined,{month:'long',year:'numeric'}));
const days = computed(() => [...Array(month.value.getDay()).fill(0), ...Array.from({length:new Date(month.value.getFullYear(),month.value.getMonth()+1,0).getDate()},(_,index) => index+1)]);
function choose(day: number) { const date = `${month.value.getFullYear()}-${String(month.value.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`; emit('update:modelValue',props.timed ? `${date}T${props.modelValue.slice(11) || (props.name === 'To' ? '23:59' : '00:00')}` : date); open.value = false; }
function time(event: Event) { const value = (event.target as HTMLInputElement).value; if (props.modelValue) emit('update:modelValue',`${props.modelValue.slice(0,10)}T${value}`); }
</script>
<template><div class="calendar-input"><button type="button" class="date-field" :aria-label="name" :aria-expanded="open" @click="open ? open = false : openCalendar()" @keydown.esc="open = false">{{ modelValue ? new Date(`${modelValue.slice(0,10)}T12:00`).toLocaleDateString() : 'Select Date' }}<span aria-hidden="true">▦</span></button><div v-if="open" class="month-picker" :aria-label="`${name} Calendar`"><div class="month-heading"><button type="button" :aria-label="`${name} Previous Month`" @click="move(-1)">‹</button><strong>{{ title }}</strong><button type="button" :aria-label="`${name} Next Month`" @click="move(1)">›</button></div><div class="days"><span v-for="day in ['Su','Mo','Tu','We','Th','Fr','Sa']" :key="day">{{ day }}</span><template v-for="(day,index) in days" :key="index"><button v-if="day" type="button" :aria-label="`${name} ${title} ${day}`" :class="{ selected: modelValue.slice(0,10) === `${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}` }" @click="choose(day)">{{ day }}</button><span v-else /></template></div></div><label v-if="timed">{{ name }} Time<input type="time" :value="modelValue.slice(11)" :disabled="!modelValue" @change="time"></label></div></template>
<style scoped>.date-field { display:flex; justify-content:space-between; width:100%; height:42px; padding:10px; color:inherit; background:var(--input-bg,#1c2430); border:1px solid var(--border,#384352); border-radius:4px; font:inherit; cursor:pointer; }.month-picker { padding:8px; border:1px solid var(--border,#384352); margin-top:8px; border-radius:4px; background:var(--input-bg,#1c2430); }.month-heading { display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; }.month-heading strong { font-size:12px; }button { cursor:pointer; color:inherit; background:transparent; border:0; font:inherit; }.month-heading button { font-size:22px; }.days { display:grid; grid-template-columns:repeat(7,1fr); gap:2px; text-align:center; }.days span,.days button { padding:7px 0; font-size:11px; }.days button:hover,.days button.selected { background:#326fb4; color:white; border-radius:3px; }label { display:flex; flex-direction:column; gap:7px; margin-top:10px; font-size:12px; }input { padding:8px; color:inherit; background:var(--input-bg,#1c2430); border:1px solid var(--border,#384352); }button:focus-visible { outline:2px solid #73b5ff; outline-offset:2px; }</style>
